def create_copies(apps, schema_editor):
    """Give every existing book its named copies and attach open loans to specific copies."""
    Book = apps.get_model('library_app', 'Book')
    BookCopy = apps.get_model('library_app', 'BookCopy')
    BorrowTransaction = apps.get_model('library_app', 'BorrowTransaction')
    for book in Book.objects.all():
        copies = [
            BookCopy.objects.create(book=book, copy_number=n, copy_code=f"BK{book.pk:04d}-C{n:02d}")
            for n in range(1, book.total_copies + 1)
        ]
        free = list(copies)
        for loan in BorrowTransaction.objects.filter(book=book, status__in=['BORROWED', 'OVERDUE']).order_by('id'):
            if free:
                loan.copy = free.pop(0)
                loan.save(update_fields=['copy'])
        if book.status in ('LOST', 'UNDER_REPAIR'):  # the whole title was flagged: flag the copies on the shelf
            for copy in free:
                copy.status = book.status
                copy.save(update_fields=['status'])
            book.available_copies = 0
            book.save(update_fields=['available_copies'])
        else:
            book.available_copies = min(book.available_copies, len(free))
            book.save(update_fields=['available_copies'])


def noop(apps, schema_editor):
    pass


